"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import "./image-reveal.css";

export interface ImageRevealProps {
  src: string;
  alt: string;
  title: string;
  caption?: string;
}

/** Pointer, keyboard, and touch share the same reveal. */
export function ImageReveal({ src, alt, title, caption }: ImageRevealProps) {
  const [open, setOpen] = useState(false);
  const reduce = useReducedMotion();
  return (
    <button
      className="forme-reveal"
      onClick={() => setOpen(!open)}
      aria-pressed={open}
      aria-label={`${open ? "Close" : "Reveal"} ${title}`}
    >
      <span className="forme-reveal-type" aria-hidden="true">
        {title}
      </span>
      <motion.img
        src={src}
        alt={alt}
        loading="lazy"
        animate={{
          clipPath: open
            ? "inset(0% 0% 0% 0% round 0px)"
            : "inset(9% 17% 9% 17% round 90px)",
          scale: open ? 1.04 : 1,
        }}
        transition={{ duration: reduce ? 0 : 0.65, ease: [0.22, 1, 0.36, 1] }}
      />
      <span className="forme-reveal-caption">
        {caption || "A different perspective"}
        <span aria-hidden="true">{open ? "−" : "+"}</span>
      </span>
    </button>
  );
}

.forme-reveal {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  min-height: 250px;
  overflow: hidden;
  border: 0;
  background: #dfe5d8;
  color: #17221b;
  cursor: pointer;
  text-align: left;
  font: inherit;
}
.forme-reveal img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.forme-reveal-type {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: clamp(70px, 12vw, 140px);
  font-weight: 500;
  letter-spacing: -0.09em;
}
.forme-reveal-caption {
  position: absolute;
  inset: auto 18px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 12px;
  border-radius: 3px;
  background: #fff;
  color: #162019;
  font-size: 12px;
}
.forme-reveal-caption > span {
  font-size: 20px;
  line-height: 1;
}
.forme-reveal:focus-visible {
  outline: 3px solid #2749ed;
  outline-offset: -4px;
}
